sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

	// Skip if location does not appear in
	// location code/Location name map.

    // User-supplied mapping of location codes 
    // to location names. Here we want just the codes.
    var locationCodes = new BaseDataSourceReader(gs.getCurrentScopeName(), "Locations")
        .getData()
        .filter(e => e.key && e.value) // filter out incomplete entries
		.map(e => e.key);

    var gr_is_row = new GlideRecord(source.getTableName());
    gr_is_row.addQuery("sys_import_set", import_set.sys_id);
    gr_is_row.addQuery("u_skip", false);
    gr_is_row.query();
    while (gr_is_row.hasNext()) {
        gr_is_row.next();

		var locationCode = gr_is_row.getValue("u_location");
		if(locationCodes.indexOf(locationCode) == -1) {
			gr_is_row.setValue("u_skip", true);
            gr_is_row.setValue("u_skip_reason", "Location not mapped");
            gr_is_row.update();
		}
    }

})(source, map, log, target);
